def compute(vars):
    decrease = vars["v1"]
    net_revenue = vars["v2"]

    if net_revenue == 0:
        return None

    value = (decrease / net_revenue) * 100

    return {
        "value": value,
        "trace": {
            "decrease_in_gross_wholesale_revenue": decrease,
            "2003_net_revenue": net_revenue,
            "ratio": decrease / net_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
